  public static ETST DeserializeFromBinary(byte[] fbBuffer) {
    return ETS.GetRootAsETS(new ByteBuffer(fbBuffer)).UnPack();
  }
  public byte[] SerializeToBinary() {
    var fbb = new FlatBufferBuilder(0x10000);
    ETS.FinishETSBuffer(fbb, ETS.Pack(fbb, this));
    return fbb.DataBuffer.ToSizedArray();
