      && verifier.VerifyField(tablePos, 6 /*SEGMENT_SEQ*/, 4 /*uint*/, 4, false)
      && verifier.VerifyField(tablePos, 8 /*TRACK_CLOSED*/, 1 /*bool*/, 1, false)
      && verifier.VerifyVectorOfTables(tablePos, 10 /*IDENTIFIERS*/, ETSIdentifierVerify.Verify, false)
      && verifier.VerifyField(tablePos, 12 /*ENVIRONMENT*/, 1 /*trackEnvironment*/, 1, false)
      && verifier.VerifyString(tablePos, 14 /*EPOCH*/, true)
      && verifier.VerifyString(tablePos, 16 /*END_EPOCH*/, true)
      && verifier.VerifyField(tablePos, 18 /*OBSERVATION_COUNT*/, 4 /*uint*/, 4, false)
      && verifier.VerifyField(tablePos, 20 /*KNOT_COUNT*/, 4 /*uint*/, 4, false)
      && verifier.VerifyField(tablePos, 22 /*SOUTH_DEG*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 24 /*NORTH_DEG*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 26 /*WEST_DEG*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 28 /*EAST_DEG*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 30 /*ALTITUDE_REFERENCE*/, 1 /*etsAltitudeDatum*/, 1, false)
      && verifier.VerifyField(tablePos, 32 /*ALTITUDE_MIN_M*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 34 /*ALTITUDE_MAX_M*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 36 /*TOLERANCE_H_M*/, 4 /*float*/, 4, false)
      && verifier.VerifyField(tablePos, 38 /*TOLERANCE_V_M*/, 4 /*float*/, 4, false)
      && verifier.VerifyField(tablePos, 40 /*ACHIEVED_MAX_ERROR_H_M*/, 4 /*float*/, 4, false)
      && verifier.VerifyField(tablePos, 42 /*ACHIEVED_MAX_ERROR_V_M*/, 4 /*float*/, 4, false)
      && verifier.VerifyField(tablePos, 44 /*CODEC*/, 1 /*etsCodec*/, 1, false)
      && verifier.VerifyField(tablePos, 46 /*CODEC_VERSION*/, 2 /*ushort*/, 2, false)
      && verifier.VerifyVectorOfData(tablePos, 48 /*PAYLOAD*/, 1 /*byte*/, true)
